import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"JipperKeyViewer","description":"","frontmatter":{"title":"JipperKeyViewer","order":5},"headers":[],"relativePath":"zh/mods/jipperkeyviewer.md","filePath":"zh/mods/jipperkeyviewer.md","lastUpdated":1786943111000}'),i={name:"zh/mods/jipperkeyviewer.md"};function l(n,e,s,d,p,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="jipperkeyviewer" tabindex="-1">JipperKeyViewer <a class="header-anchor" href="#jipperkeyviewer" aria-label="Permalink to &quot;JipperKeyViewer&quot;">​</a></h1><blockquote><p>ADOFAI <strong>按键显示</strong> Mod：实时显示按键按下、KPS 统计与雨滴特效。支持 <strong>UnityModManager</strong> 与 <strong>MelonLoader</strong>，界面支持中 / 英 / 韩三语。</p><p>项目地址：<a href="https://github.com/adofaiex/JipperKeyViewer" target="_blank" rel="noreferrer">https://github.com/adofaiex/JipperKeyViewer</a></p></blockquote><h2 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>说明</th></tr></thead><tbody><tr><td><strong>JipperKeyViewer</strong></td><td>标准版，从 <code>keyviewer_resources</code> AssetBundle 加载资源</td></tr><tr><td><strong>JipperKeyViewer-FileBased</strong></td><td>直接从 PNG/OTF 文件加载图片/字体，无需 AssetBundle</td></tr></tbody></table><p>两个版本功能完全一致，均支持 UMM 与 MelonLoader。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>布局</strong>：8K / 10K / 12K / 14K / 16K / 20K / 24K，以及完整 <strong>108 键</strong>物理键盘，脚键 2K–16K</li><li>KPS 统计与总按键计数，每键独立 KPS</li><li><strong>雨滴特效</strong>：松开按键时平滑淡出；<strong>鬼键雨滴</strong>只触发雨滴、不显示</li><li>每排雨滴独立控制（速度、高度、开关）</li><li>每键独立颜色、自动彩虹 KV；KPS / Total 独立颜色</li><li><strong>标准按键宽度</strong>：宽窄混排后排统一为 50px</li><li><strong>108 键全键盘</strong>：完整 QWERTY + 小键盘，整块可移动</li><li>KPS/Total 文本居中（随数值变长自动重排）</li><li>流媒体模式（隐藏 KPS/Total）、千分位格式化</li><li>字体样式（粗体/斜体/下划线）、自定义字体（把 <code>.ttf/.otf</code> 放入 <code>CustomFont/</code> 自动识别）</li><li>归一化自定义位置（0–1），自动适配任意分辨率</li><li>按键绑定修改与自定义文本标签</li><li>对象池与合并渲染，热路径零 GC 分配</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="unity-mod-manager" tabindex="-1">Unity Mod Manager <a class="header-anchor" href="#unity-mod-manager" aria-label="Permalink to &quot;Unity Mod Manager&quot;">​</a></h3><ol><li>安装 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UMM</a></li><li>从 <a href="https://github.com/adofaiex/JipperKeyViewer/releases" target="_blank" rel="noreferrer">Releases</a> 下载 <strong>UMM</strong> 版本</li><li>通过 UMM 安装，或解压到 <code>ADOFAI/Mods/JipperKeyViewer/</code></li></ol><h3 id="melonloader" tabindex="-1">MelonLoader <a class="header-anchor" href="#melonloader" aria-label="Permalink to &quot;MelonLoader&quot;">​</a></h3><ol><li>安装 <a href="https://melonwiki.xyz/" target="_blank" rel="noreferrer">MelonLoader</a></li><li>从 Releases 下载 <strong>MelonLoader</strong> 版本</li><li>解压到 <code>ADOFAI/Mods/JipperKeyViewer-melon/</code></li><li>游戏内按 <strong>F7</strong> 打开设置（可改键）</li></ol><h2 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to &quot;疑难解答&quot;">​</a></h2><blockquote><p>📝 待补充（欢迎在仓库 Issues 中反馈）</p></blockquote>',14)])])}const u=r(i,[["render",l]]);export{g as __pageData,u as default};
